function paint(material,value){const color=valid(value?.color)?value.color:DEFAULT_FINISH;material.color.set(value?.wood?'#ffffff':color);material.userData.compatColor=color;material.map?.dispose();material.map=value?.texture&&/^\.\.\/catalogue\/[a-z0-9-]+\.webp$/i.test(value.texture)?new T.TextureLoader().load(value.texture):textureFor(color,!!value?.wood);if(value?.texture){material.color.set('#ffffff');material.map.colorSpace=T.SRGBColorSpace;}material.roughness=value?.wood ? .42 : .07;material.clearcoat=value?.wood ? .3 : 1;material.clearcoatRoughness=value?.wood ? .3 : .025;material.ior=1.49;material.specularIntensity=1;material.envMapIntensity=1.25;material.needsUpdate=true;}
