function finish(value){if(!selected)return;const list=$('scope').value==='all'?model.units.filter(u=>u.kind!=='dishwasher'):selected.members;for(const u of list){if(u.kind==='dishwasher')continue;const f=saved.finishes[u.id]||{};if(surface==='both'||surface==='front')f.front={...value};if(surface==='both'||surface==='side')f.side={...value};saved.finishes[u.id]=f;paint(u.front,f.front);paint(u.side,f.side);paint(u.sideSkin,f.side);}const ok=persist();if(ok)$('finishStatus').textContent=value.name+' applied to '+($('scope').value==='all'?'all cabinetry':selected.name)+'. Saved in this browser.';$('customColor').value=value.color;guide(3,'Open it. Explore inside.','Tap a shutter or drawer, or press Open doors / drawers.');markSwatches();}
function markSwatches(){const f=saved.finishes[selected?.members[0]?.id]?.[surface==='side'?'side':'front'];document.querySelectorAll('.swatch').forEach(b=>b.setAttribute('aria-pressed',String(f?.texture?b.dataset.texture===f.texture:!b.dataset.texture&&b.dataset.color===(f?.color||DEFAULT_FINISH))));}
