function bounds(item=selected){return new T.Box3().setFromObject(item?.group||model.root);}
function fit(item=selected,direction){const b=bounds(item),center=b.getCenter(new T.Vector3()),size=b.getSize(new T.Vector3());const aspect=stage.clientWidth/Math.max(1,stage.clientHeight),fov=camera.fov*Math.PI/180;const radius=size.length()/2;const distance=Math.max(radius/Math.sin(fov/2),radius/Math.sin(Math.atan(Math.tan(fov/2)*aspect)))*(item?1.18:1.08);const n=direction|| (item?new T.Vector3(Math.sin(item.angle+.65),.30,Math.cos(item.angle+.65)):new T.Vector3(.52,.70,1));n.normalize();motion={from:camera.position.clone(),to:center.clone().addScaledVector(n,distance),fromTarget:controls.target.clone(),target:center,start:performance.now()};controls.minDistance=Math.max(.22,size.length()*.12);controls.maxDistance=30;}
function select(u,scroll=false){if(referenceMode){referenceMode=false;model.setReference(false);$('reference').setAttribute('aria-pressed','false');}u=u.product||u;selected=u;document.querySelector('.studio').classList.add('is-focused');document.body.style.overflow='hidden';auto=false;controls.autoRotate=false;$('auto').setAttribute('aria-pressed','false');$('focus').checked=true;for(const product of model.products)product.group.visible=product===u;for(const unit of model.units)unit.group.visible=u.members.includes(unit);model.architecture.visible=false;$('itemName').textContent=u.name;$('viewLabel').textContent='YOUR KITCHEN · INDIVIDUAL UNIT';$('specButton').hidden=false;$('quoteItemLabel').hidden=false;$('quoteItem').checked=u.members.some(member=>saved.quotationItems[member.id]);$('openSelected').hidden=false;$('closeSelected').hidden=false;$('finishes').hidden=u.kind==='dishwasher';$('hint').textContent='Drag to rotate · Move to reposition · Tap a door or drawer to open';guide(2,u.kind==='dishwasher'?'See how it opens.':'Try a finish you love.',u.kind==='dishwasher'?'Tap the front door to open it.':'Swipe the mica strip below and tap a colour.');for(const btn of $('unitList').children)btn.setAttribute('aria-pressed',String(btn.dataset.unit===u.id));const current=saved.finishes[u.members[0].id]?.front;$('customColor').value=valid(current?.color)?current.color:DEFAULT_FINISH;$('finishStatus').textContent=current?'Current finish: '+current.name+'. Saved in this browser.':'Swipe and tap a finish. Your choices save automatically in this browser.';markSwatches();fit(u);}
function showAll(){selected=null;document.querySelector('.studio').classList.remove('is-focused');document.body.style.overflow='';$('focus').checked=false;for(const u of model.products)u.group.visible=true;for(const u of model.units)u.group.visible=true;model.architecture.visible=true;$('finishes').hidden=true;$('specButton').hidden=true;$('quoteItemLabel').hidden=true;$('openSelected').hidden=true;$('closeSelected').hidden=true;$('itemName').textContent='See the whole picture.';$('viewLabel').textContent='FULL KITCHEN';$('hint').textContent='Drag to rotate · Pinch to zoom · Tap a cabinet to explore';guide(1,'Start with your kitchen','Drag to rotate. Tap any cabinet to explore it.');for(const b of $('unitList').children)b.setAttribute('aria-pressed','false');fit(null);}
