function drawPalette(list){$('swatches').replaceChildren();for(const p of list){const b=document.createElement('button');b.className='swatch';b.dataset.color=p.color;if(p.texture)b.dataset.texture=p.texture;b.setAttribute('aria-label','Apply '+p.name+(p.wood?' wood-grain mica':' glossy mica'));b.setAttribute('aria-pressed','false');const c=document.createElement('span');c.className='chip '+(p.wood?'wood':'gloss');c.style.setProperty('--colour',p.color);if(p.texture){const img=document.createElement('img');img.src=p.texture;img.alt=p.name;img.loading='lazy';c.append(img);}const title=document.createElement('b');title.textContent=p.name;const type=document.createElement('small');type.textContent=p.code|| (p.wood?'Wood grain':'Gloss finish');b.append(c,title,type);b.onclick=()=>finish(p);$('swatches').append(b);}markSwatches();}
async function catalogueMode(on){$('paletteMode').setAttribute('aria-pressed',String(!on));$('catalogueMode').setAttribute('aria-pressed',String(on));$('catalogueSearch').hidden=!on;if(!on){drawPalette(palette);return;}if(!catalogueLoaded){try{const r=await fetch('../catalogue/catalogue.json');if(!r.ok)throw Error('catalogue');const d=await r.json();catalogue=d.samples.map(s=>({name:s.name||s.code,code:s.code,color:'#9b8b75',texture:'../'+s.image}));catalogueLoaded=true;}catch{$('finishStatus').textContent='Catalogue unavailable. Preview colours are still available.';drawPalette(palette);return;}}const q=$('catalogueSearch').value.toLowerCase();drawPalette(catalogue.filter(p=>(p.name+' '+p.code).toLowerCase().includes(q)));}
