 $('sageFinish').onclick=()=>{referenceMode=false;model.setReference(false);$('reference').setAttribute('aria-pressed','false');for(const u of model.units){if(u.kind==='dishwasher')continue;const v={name:'Studio blue acrylic',color:DEFAULT_FINISH};saved.finishes[u.id]={front:{...v},side:{...v}};paint(u.front,v);paint(u.side,v);paint(u.sideSkin,v);}persist();showAll();$('hint').textContent='Original studio blue-acrylic finish applied to all cabinetry · tap a unit to explore';};$('reference').onclick=()=>{const next=!referenceMode;showAll();referenceMode=next;model.setReference(next);$('reference').setAttribute('aria-pressed',String(next));$('hint').textContent=next?'Original SKP faces and identification colours · tap a unit to explore its finished version':'Drag to rotate · Pinch to zoom · Tap a cabinet to explore';};$('rotate').onclick=()=>mode(false);$('move').onclick=()=>mode(true);
 $('front').onclick=()=>fit(selected,selected?new T.Vector3(Math.sin(selected.angle),.10,Math.cos(selected.angle)):new T.Vector3(.15,.3,1));$('top').onclick=()=>fit(selected,new T.Vector3(.001,1,.001));
