function frame(now){const dt=Math.min(.05,(now-(last||now))/1000);last=now;model.update(dt);if(motion){const t=Math.min(1,(now-motion.start)/650),s=1-(1-t)**3;camera.position.lerpVectors(motion.from,motion.to,s);controls.target.lerpVectors(motion.fromTarget,motion.target,s);if(t===1)motion=null;}controls.update();renderer.render(scene,camera);requestAnimationFrame(frame);}
